/* GCHE2 · Temas de estudio armados: resumen, 30 preguntas tipo ENARM, repaso en audio y fuentes. Redactados con palabras propias a partir de la bibliografía citada en cada tema. Solo enlaces a sitios .gob.mx. */
window.SXTEMAS={"cardiologia-14":{"titulo":"Hipertensión arterial en la consulta","enfoque":"Enfoque de consulta de primer nivel: medición correcta, confirmación del diagnóstico, metas, tratamiento escalonado y manejo de la crisis hipertensiva.","resumen":[{"h":"Lo esencial en 30 segundos","li":["Hipertensión: presión en consultorio de **140/90 mmHg o más**, confirmada en al menos dos visitas o con mediciones fuera del consultorio.","Es el principal factor de riesgo de **evento vascular cerebral** y de enfermedad cardiovascular; casi siempre es asintomática.","La causa más frecuente es la **esencial**; entre las secundarias, las **renales**, y entre las endocrinas, el **hiperaldosteronismo primario**.","Todos reciben medidas de estilo de vida; la mayoría inicia con **doble terapia**, de preferencia en una sola tableta.","Meta: **menor de 130/80 mmHg** si se tolera; en adultos mayores frágiles, presión sistólica de 140 a 150 mmHg."]},{"h":"Clasificación en consultorio","li":["Óptima: menor de 120/80. Normal: 120 a 129 y/o 80 a 84. Normal alta: 130 a 139 y/o 85 a 89.","**Grado 1**: 140 a 159 y/o 90 a 99. **Grado 2**: 160 a 179 y/o 100 a 109. **Grado 3**: 180 o más y/o 110 o más.","Sistólica aislada: 140 o más con diastólica menor de 90; típica del adulto mayor por rigidez arterial.","Fuera del consultorio: con medición en casa, **135/85** o más; con monitoreo de 24 horas, 135/85 de día y **120/70 de noche**."]},{"h":"Cómo medir bien","li":["Paciente sentado **5 minutos** en reposo, espalda apoyada, piernas sin cruzar, brazo descubierto y apoyado a la altura del corazón.","Sin café, tabaco ni ejercicio en los 30 minutos previos; vejiga vacía; sin hablar.","Brazalete del tamaño correcto: uno pequeño da cifras falsamente altas.","La primera vez, medir **ambos brazos** y usar el más alto. Tomar 2 o 3 lecturas separadas 1 a 2 minutos y promediar.","El protocolo del Instituto Mexicano del Seguro Social confirma con monitoreo en casa: **dos mediciones al día por 10 días**."]},{"h":"Fenómenos que se preguntan","li":["**Bata blanca**: alta en consultorio, normal fuera. **Enmascarada**: normal en consultorio, alta fuera; se trata como hipertensión.","**Patrón non-dipper**: la presión no baja de noche; obliga a buscar **apnea obstructiva del sueño**.","**Seudohipertensión** del anciano por arterias rígidas: signo de Osler (la radial se sigue palpando con el brazalete inflado)."]},{"h":"Evaluación inicial","li":["Laboratorio: glucosa, creatinina con filtración glomerular, sodio y potasio, perfil de lípidos, ácido úrico, biometría hemática y examen general de orina con albuminuria.","Electrocardiograma (busca **hipertrofia ventricular izquierda**) y fondo de ojo.","Estimar el riesgo cardiovascular global y buscar daño a órgano blanco: corazón, riñón, cerebro, retina y arterias periféricas."]},{"h":"Cuándo sospechar hipertensión secundaria","li":["Inicio **antes de los 30 años** o descontrol súbito en un hipertenso antes controlado.","Hipertensión resistente o grado 3, o daño a órgano blanco desproporcionado.","**Hipopotasemia** espontánea con alcalosis metabólica: hiperaldosteronismo primario.","Crisis de cefalea, sudoración y palpitaciones: feocromocitoma.","Elevación de creatinina más de 30% al iniciar un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina: estenosis de arteria renal.","Ronquido, somnolencia diurna y obesidad: apnea obstructiva del sueño.","Fármacos: **antiinflamatorios no esteroideos**, anticonceptivos orales, corticoides, descongestionantes, alcohol."]},{"h":"Estilo de vida para todos","li":["Sal **menor de 5 g al día** (una cucharadita).","Ejercicio aeróbico **30 minutos al día**, 5 a 7 días por semana.","Bajar de peso: por cada 5 kg perdidos baja la presión sistólica unos 5 mmHg y la diastólica unos 3 mmHg.","Alcohol: menos de 20 g al día en hombres y menos de 10 g en mujeres; dejar de fumar.","Dieta rica en frutas y verduras (dieta DASH, siglas en inglés de enfoques dietéticos para detener la hipertensión)."]},{"h":"Cuándo iniciar fármacos","li":["**Grados 2 y 3**: fármaco desde el inicio, junto con estilo de vida.","**Grado 1 con alto riesgo** (diabetes, enfermedad renal, enfermedad cardiovascular o daño a órgano blanco): fármaco desde el inicio.","Grado 1 de bajo riesgo: 3 a 6 meses de estilo de vida y, si no se controla, fármaco.","Presión normal alta: no se dan fármacos."]},{"h":"Esquema farmacológico por pasos","li":["**Paso 1, doble terapia**: inhibidor de la enzima convertidora de angiotensina o antagonista del receptor de angiotensina II **más** calcioantagonista o diurético tiazídico. Monoterapia solo en grado 1 de bajo riesgo o en adultos mayores frágiles.","**Paso 2, triple terapia**: los tres grupos juntos.","**Paso 3**: agregar **espironolactona** (revisar antes potasio y función renal).","Los betabloqueadores se usan en cualquier paso si hay indicación: cardiopatía isquémica, insuficiencia cardiaca, control de frecuencia en fibrilación auricular.","**Nunca** combinar un inhibidor de la enzima convertidora con un antagonista del receptor de angiotensina II.","El protocolo del Instituto Mexicano del Seguro Social inicia con inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más indapamida o hidroclorotiazida, y agrega calcioantagonista si no hay meta en 2 semanas."]},{"h":"Dosis habituales en adultos","li":["Losartán: **50 mg una vez al día**; rango de 25 a 100 mg al día.","Enalapril: inicio **5 mg al día** (2.5 mg si toma diurético); mantenimiento de 10 a 40 mg al día en 1 o 2 tomas.","Amlodipino: **5 mg una vez al día**, máximo 10 mg; 2.5 mg en adultos mayores frágiles.","Hidroclorotiazida o clortalidona: 12.5 a 25 mg una vez al día.","Vigilar creatinina y potasio a las 1 a 2 semanas de iniciar o subir un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina."]},{"h":"Qué fármaco según el paciente","li":["Diabetes, albuminuria o enfermedad renal crónica: **inhibidor de la enzima convertidora o antagonista del receptor de angiotensina II**.","Adulto mayor con sistólica aislada: **calcioantagonista** o tiazida.","Embarazo: **alfametildopa**, labetalol o nifedipino. **Contraindicados** inhibidores de la enzima convertidora y antagonistas del receptor de angiotensina.","Hiperplasia prostática: alfabloqueador como fármaco agregado.","Asma: **evitar betabloqueadores**.","Gota: evitar tiazidas. Tos seca con enalapril: cambiar a un antagonista del receptor de angiotensina II.","Edema de tobillos con amlodipino: efecto de clase de las dihidropiridinas, no es insuficiencia cardiaca."]},{"h":"Hipertensión resistente","li":["Presión fuera de meta con **tres fármacos a dosis óptimas, uno de ellos diurético**.","Primero descartar seudorresistencia: **falta de apego** (la causa más frecuente), mala técnica, bata blanca (confirmar con monitoreo de 24 horas), sal y antiinflamatorios.","Cuarto fármaco de elección: **espironolactona**.","Buscar causa secundaria y referir a cardiología o medicina interna."]},{"h":"Crisis hipertensiva","li":["Presión sistólica de **180 o más** y/o diastólica de **120 o más**.","**Urgencia hipertensiva**: sin daño agudo de órgano blanco. Se maneja con fármacos **orales**, bajando la presión de forma gradual en **24 a 48 horas**; revisar el apego y citar pronto.","**Emergencia hipertensiva**: con daño agudo (encefalopatía, evento vascular cerebral, síndrome coronario agudo, edema pulmonar, disección aórtica, lesión renal aguda o eclampsia). **Referencia inmediata** para tratamiento intravenoso.","No usar nifedipino sublingual: la caída brusca puede causar isquemia cerebral o coronaria."]},{"h":"Seguimiento y referencia","li":["Tras iniciar o ajustar: revalorar en **2 a 4 semanas**; la meta debe alcanzarse en unos **3 meses**.","Ya controlado: cada 3 a 6 meses.","Referir: emergencia hipertensiva, sospecha de hipertensión secundaria, hipertensión resistente, embarazo con hipertensión o daño renal que progresa."]}],"perlas":["Diagnóstico: **dos visitas** o confirmación fuera del consultorio; bata blanca se descarta con monitoreo de 24 horas.","Inicio con **doble terapia** casi siempre; monoterapia solo en grado 1 de bajo riesgo o anciano frágil.","Cuarto fármaco en la resistente: **espironolactona**.","Embarazo: **alfametildopa**; nunca inhibidores de la enzima convertidora ni antagonistas del receptor de angiotensina.","Hipopotasemia más hipertensión: piensa en **hiperaldosteronismo primario**.","Urgencia sin daño de órgano: **orales y bajar gradual**; emergencia con daño: **intravenoso y referencia**."],"mexico":["El Manual CTO sigue las guías europeas. En México rigen la Guía de Práctica Clínica de hipertensión en el primer nivel de atención del Centro Nacional de Excelencia Tecnológica en Salud (2021) y el Protocolo de Atención Integral de hipertensión del Instituto Mexicano del Seguro Social (2022).","El protocolo mexicano fija la meta general en **menor de 130/80 sin bajar de 110/70**, y **menor de 140/90 en el adulto mayor**.","En el Instituto Mexicano del Seguro Social la doble terapia inicial es inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más indapamida o hidroclorotiazida; el calcioantagonista se agrega como segundo paso o se prefiere desde el inicio si hay riesgo cardiometabólico o diabetes.","La guía de Estados Unidos define hipertensión desde 130/80; en el ENARM se usa el corte de 140/90."],"preguntas":[{"c":"Hombre de 46 años con presión de 152/96 mmHg en una sola consulta. Asintomático, sin otros factores de riesgo.","p":"¿Cuál es la conducta correcta?","o":["Diagnosticar hipertensión e iniciar doble terapia","Confirmar con otra visita o con mediciones fuera del consultorio","Iniciar betabloqueador","Solicitar ecocardiograma de inmediato"],"r":1,"e":"El diagnóstico exige elevación confirmada en al menos dos visitas o fuera del consultorio con medición en casa o monitoreo de 24 horas, salvo crisis o daño a órgano blanco.","f":"Manual CTO, Cardiología, capítulo 14, medida de la presión arterial."},{"c":"Paciente con presión de 166/104 mmHg confirmada en dos visitas.","p":"¿En qué grado se clasifica?","o":["Grado 1","Grado 2","Grado 3","Normal alta"],"r":1,"e":"Grado 2: sistólica de 160 a 179 y/o diastólica de 100 a 109. Si la sistólica y la diastólica caen en grados distintos, se clasifica por el más alto.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.1."},{"c":"Mujer de 74 años con presiones de 158/78 mmHg repetidas.","p":"¿Qué tipo de hipertensión presenta?","o":["Hipertensión diastólica","Hipertensión sistólica aislada","Presión normal para la edad","Seudohipertensión confirmada"],"r":1,"e":"Sistólica de 140 o más con diastólica menor de 90 es hipertensión sistólica aislada, típica del adulto mayor por rigidez arterial; aumenta el riesgo de eventos y se trata.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Mujer de 40 años con presiones de 150/95 en consultorio, pero su registro en casa promedia 122/76 y el monitoreo de 24 horas es normal con descenso nocturno.","p":"¿Cuál es el diagnóstico?","o":["Hipertensión enmascarada","Hipertensión de bata blanca","Hipertensión grado 1","Hipertensión resistente"],"r":1,"e":"Cifras altas solo en consultorio con mediciones normales fuera son hipertensión de bata blanca. La enmascarada es lo contrario.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.1."},{"c":"Hombre de 52 años con obesidad, ronquidos y somnolencia diurna. El monitoreo de 24 horas muestra que su presión no baja durante la noche.","p":"¿Qué causa debes descartar?","o":["Feocromocitoma","Apnea obstructiva del sueño","Coartación aórtica","Hipotiroidismo"],"r":1,"e":"El patrón non-dipper obliga a descartar apnea obstructiva del sueño, causa frecuente de hipertensión secundaria y resistente; se confirma con polisomnografía y mejora con presión positiva continua.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Al medir la presión de un paciente, el médico usa un brazalete estándar en un brazo muy grueso.","p":"¿Qué error de medición se produce?","o":["Cifras falsamente bajas","Cifras falsamente altas","No cambia el resultado","Solo cambia la diastólica"],"r":1,"e":"Un brazalete pequeño para el brazo sobrestima la presión; uno grande la subestima. Por eso se usa el brazalete adecuado al perímetro del brazo.","f":"Harrison, 21.ª edición, capítulo 277."},{"c":"Mujer de 28 años con hipertensión de reciente inicio, debilidad muscular y potasio de 2.9 mEq/L sin uso de diuréticos.","p":"¿Cuál es la sospecha principal?","o":["Hipertensión esencial","Hiperaldosteronismo primario","Síndrome de Cushing","Feocromocitoma"],"r":1,"e":"Hipertensión con hipopotasemia espontánea y alcalosis metabólica orienta a hiperaldosteronismo primario, la causa endocrina más frecuente de hipertensión secundaria. Se estudia con el cociente aldosterona/renina.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Hipertenso de 68 años con aterosclerosis. Dos semanas después de iniciar enalapril su creatinina subió de 1.0 a 1.6 mg/dL.","p":"¿Qué debes sospechar?","o":["Nefropatía por enalapril","Estenosis de arteria renal","Deshidratación leve sin importancia","Efecto esperado sin consecuencias"],"r":1,"e":"Un aumento de creatinina mayor de 30% al iniciar un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina sugiere estenosis de arteria renal, sobre todo en ancianos con aterosclerosis.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Paciente con hipertensión de difícil control que toma diclofenaco diario por dolor de rodilla.","p":"¿Qué recomiendas primero?","o":["Agregar un cuarto antihipertensivo","Suspender o sustituir el antiinflamatorio no esteroideo","Aumentar la dosis del diurético","Referir a cardiología"],"r":1,"e":"Los antiinflamatorios no esteroideos retienen sodio, suben la presión y reducen el efecto de los antihipertensivos. Es una causa de seudorresistencia que se corrige antes de agregar fármacos.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 50 años con hipertensión grado 1, sin diabetes, sin daño a órgano blanco y riesgo cardiovascular bajo.","p":"¿Cuál es la conducta inicial?","o":["Doble terapia inmediata","Medidas de estilo de vida por 3 a 6 meses y revalorar","No hacer nada","Betabloqueador como primera línea"],"r":1,"e":"En grado 1 de bajo riesgo se intenta primero el manejo no farmacológico; si no se controla en 3 a 6 meses, se inicia fármaco.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.4."},{"c":"Paciente de 55 años con presión de 168/102 mmHg confirmada, sin otras enfermedades.","p":"¿Cuál es el tratamiento inicial recomendado?","o":["Monoterapia con hidroclorotiazida","Doble terapia, de preferencia en una sola tableta","Solo cambios de estilo de vida por 6 meses","Espironolactona"],"r":1,"e":"En grados 2 y 3 se inicia de entrada doble terapia (inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más calcioantagonista o tiazida) junto con el estilo de vida.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.4."},{"c":"Paciente hipertenso con losartán, amlodipino e hidroclorotiazida a dosis óptimas, con buen apego confirmado y monitoreo de 24 horas en 148/92.","p":"¿Cuál es el siguiente fármaco de elección?","o":["Enalapril","Espironolactona","Atenolol","Clonidina"],"r":1,"e":"Es hipertensión resistente verdadera. El cuarto fármaco de elección es la espironolactona; revisar antes potasio y función renal, y buscar causa secundaria.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente hipertenso con enalapril y presión aún elevada. Se plantea agregar losartán.","p":"¿Es correcta esta combinación?","o":["Sí, potencia el bloqueo del sistema renina-angiotensina","No, combinarlos aumenta hiperpotasemia y lesión renal sin beneficio","Sí, pero solo en diabéticos","Sí, si la creatinina es normal"],"r":1,"e":"El doble bloqueo con inhibidor de la enzima convertidora y antagonista del receptor de angiotensina II no reduce eventos y aumenta hiperpotasemia y daño renal. Se agrega calcioantagonista o tiazida.","f":"Guía de hipertensión de la Sociedad Europea de Cardiología; Harrison, 21.ª edición, capítulo 277."},{"c":"Mujer de 45 años, hipertensa, con enalapril, que refiere tos seca persistente desde que lo inició.","p":"¿Qué haces?","o":["Agregar un antitusivo","Cambiar a un antagonista del receptor de angiotensina II","Suspender todo tratamiento","Cambiar a betabloqueador"],"r":1,"e":"La tos seca por acumulación de bradicinina es efecto de clase de los inhibidores de la enzima convertidora. Los antagonistas del receptor de angiotensina II no la producen.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente con hipertensión y asma bronquial.","p":"¿Qué grupo de antihipertensivos está contraindicado?","o":["Calcioantagonistas","Betabloqueadores","Tiazidas","Antagonistas del receptor de angiotensina II"],"r":1,"e":"Los betabloqueadores pueden causar broncoespasmo y están contraindicados en asma.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Hombre de 58 años hipertenso con gota de repetición.","p":"¿Qué fármaco conviene evitar?","o":["Losartán","Hidroclorotiazida","Amlodipino","Enalapril"],"r":1,"e":"Las tiazidas elevan el ácido úrico y desencadenan crisis de gota. El losartán, en cambio, tiene un leve efecto uricosúrico.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Mujer de 32 años con 14 semanas de embarazo e hipertensión crónica. Tomaba losartán.","p":"¿Qué cambio realizas?","o":["Mantener losartán","Cambiar a alfametildopa","Cambiar a enalapril","Suspender todo antihipertensivo"],"r":1,"e":"Los inhibidores de la enzima convertidora y los antagonistas del receptor de angiotensina son teratógenos y están contraindicados. Opciones en embarazo: alfametildopa, labetalol o nifedipino.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 70 años con hipertensión y crecimiento prostático con síntomas urinarios. Presión aún elevada con dos fármacos.","p":"¿Qué fármaco agregado aprovecha ambas condiciones?","o":["Betabloqueador","Alfabloqueador como la doxazosina","Diurético de asa","Clonidina"],"r":1,"e":"Los alfabloqueadores mejoran los síntomas de la hiperplasia prostática y bajan la presión. Se usan como fármaco agregado y causan hipotensión ortostática.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente con diabetes tipo 2, hipertensión y albuminuria de 120 mg/g.","p":"¿Qué grupo debe formar parte de su tratamiento?","o":["Betabloqueador","Inhibidor de la enzima convertidora o antagonista del receptor de angiotensina II","Calcioantagonista no dihidropiridínico solo","Alfametildopa"],"r":1,"e":"En diabetes con albuminuria, los bloqueadores del sistema renina-angiotensina reducen la proteinuria y retrasan la progresión renal.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente que inicia amlodipino 10 mg y al mes refiere edema en ambos tobillos, sin disnea.","p":"¿Cuál es la causa más probable?","o":["Insuficiencia cardiaca","Efecto adverso de las dihidropiridinas por vasodilatación arteriolar","Trombosis venosa bilateral","Síndrome nefrótico"],"r":1,"e":"El edema de tobillos es dosis dependiente con las dihidropiridinas. Se puede bajar la dosis o combinarlo con un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina, que lo reduce.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente de 60 años, hipertensa, con presión de 186/112 mmHg. Asintomática, sin dolor torácico, sin déficit neurológico; electrocardiograma y examen de orina sin cambios agudos. Dejó sus fármacos hace una semana.","p":"¿Cuál es la conducta adecuada?","o":["Nifedipino sublingual para bajarla rápido","Reiniciar o ajustar fármacos orales y bajar la presión de forma gradual en 24 a 48 horas","Nitroprusiato intravenoso en el consultorio","Referir a terapia intensiva"],"r":1,"e":"Es una urgencia hipertensiva: no hay daño agudo de órgano blanco. Se maneja con fármacos orales, descenso gradual y revaloración cercana. El nifedipino sublingual está proscrito.","f":"Manual CTO, Cardiología, capítulo 14, crisis hipertensivas."},{"c":"Hombre de 58 años con presión de 210/128 mmHg, cefalea intensa, confusión y vómito.","p":"¿Cómo se clasifica y qué haces?","o":["Urgencia hipertensiva; captopril oral y alta","Emergencia hipertensiva; referencia inmediata para tratamiento intravenoso","Hipertensión grado 3 estable; doble terapia oral","Crisis de ansiedad; benzodiacepina"],"r":1,"e":"Hay daño agudo de órgano blanco (encefalopatía hipertensiva), por lo que es emergencia. Requiere fármacos intravenosos con monitoreo y reducción controlada de la presión.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente que pregunta cuánta sal puede comer al día.","p":"¿Cuál es la recomendación?","o":["Menos de 10 g al día","Menos de 5 g al día","No hay límite si toma fármacos","Eliminar por completo el sodio"],"r":1,"e":"Se recomienda restringir la sal a menos de 3 a 5 g diarios, equivalentes a una cucharadita.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.4."},{"c":"Paciente hipertenso con obesidad que pierde 10 kg.","p":"¿Cuánto se espera que baje su presión sistólica?","o":["2 mmHg","Unos 10 mmHg","30 mmHg","No cambia"],"r":1,"e":"Por cada 5 kg perdidos la presión sistólica baja unos 5 mmHg y la diastólica unos 3 mmHg; con 10 kg, alrededor de 10 mmHg de sistólica.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hipertenso de 50 años, sin comorbilidades, con buena tolerancia al tratamiento.","p":"¿Cuál es la meta de presión recomendada?","o":["Menor de 150/90 mmHg","Menor de 130/80 mmHg","Menor de 110/60 mmHg","Menor de 160/100 mmHg"],"r":1,"e":"Si se tolera, la meta en menores de 65 años es menor de 130/80 mmHg; el protocolo mexicano agrega no bajar de 110/70.","f":"Manual CTO, Cardiología, capítulo 14; Protocolo de Atención Integral de hipertensión, Instituto Mexicano del Seguro Social."},{"c":"Mujer de 84 años, frágil, con caídas por mareo al levantarse. Presión sentada de 128/70 con tres antihipertensivos.","p":"¿Qué haces?","o":["Agregar un cuarto fármaco para llegar a 120/70","Reducir el tratamiento; en adultos mayores frágiles se aceptan metas más laxas","Mantener todo igual","Iniciar fludrocortisona"],"r":1,"e":"En el anciano frágil, cifras bajas favorecen la hipotensión ortostática y las caídas sin mejorar la supervivencia; se aceptan metas de sistólica de 140 a 150 mmHg.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 22 años con hipertensión grado 2, pulsos femorales débiles y presión menor en las piernas que en los brazos.","p":"¿Cuál es el diagnóstico más probable?","o":["Hipertensión esencial","Coartación aórtica","Feocromocitoma","Estenosis de arteria renal por aterosclerosis"],"r":1,"e":"Hipertensión en brazos con presión baja y pulsos débiles en piernas sugiere coartación aórtica. Toda hipertensión antes de los 30 años obliga a buscar causa secundaria.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Electrocardiograma de un hipertenso de larga evolución con ondas R altas en V5, V6, DI y aVL, y descenso del segmento ST con ondas T negativas asimétricas en esas derivaciones.","p":"¿Qué muestra?","o":["Isquemia subepicárdica","Hipertrofia ventricular izquierda con sobrecarga","Bloqueo de rama derecha","Pericarditis"],"r":1,"e":"Los voltajes altos en derivaciones laterales con alteraciones del ST-T asimétricas indican hipertrofia ventricular izquierda, el daño cardiaco típico de la hipertensión y un factor de riesgo independiente.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.3."},{"c":"Paciente que inicia losartán por hipertensión y enfermedad renal crónica leve.","p":"¿Qué debes vigilar en 1 a 2 semanas?","o":["Glucosa y hemoglobina glucosilada","Creatinina y potasio","Transaminasas","Ácido úrico y calcio"],"r":1,"e":"Los bloqueadores del sistema renina-angiotensina pueden elevar el potasio y la creatinina; se miden al inicio y tras cada aumento de dosis.","f":"Ficha de losartán de GCHE2 (etiqueta oficial); Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente con hipertensión, al que se le inicia doble terapia.","p":"¿Cuándo debes revalorarlo?","o":["En 6 meses","En 2 a 4 semanas","Solo si presenta síntomas","En un año"],"r":1,"e":"Tras iniciar o ajustar el tratamiento se revalora en 2 a 4 semanas, con meta de control en unos 3 meses; el protocolo mexicano escala a triple terapia si no hay meta en 2 semanas.","f":"Protocolo de Atención Integral de hipertensión, Instituto Mexicano del Seguro Social, 2022."}],"audio":[["¿Desde qué cifra hay hipertensión en consultorio?","Desde 140 de sistólica o 90 de diastólica, confirmada en dos visitas o con mediciones fuera del consultorio."],["¿Cuáles son los grados?","Grado 1, de 140 a 159 sobre 90 a 99; grado 2, de 160 a 179 sobre 100 a 109; grado 3, de 180 sobre 110 o más."],["¿Cuál es el corte fuera del consultorio?","135 sobre 85 en casa o de día; 120 sobre 70 de noche en el monitoreo de 24 horas."],["¿Qué es la hipertensión de bata blanca?","Presión alta solo en consultorio y normal fuera. La enmascarada es al revés y se trata."],["¿Con qué se inicia el tratamiento?","Estilo de vida para todos y, en la mayoría, doble terapia: inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más calcioantagonista o tiazida."],["¿Cuándo se permite monoterapia?","En grado 1 de bajo riesgo y en adultos mayores frágiles."],["¿Cuál es la meta?","Menor de 130 sobre 80 si se tolera; en ancianos frágiles, sistólica de 140 a 150."],["¿Qué es hipertensión resistente y qué se agrega?","Falta de control con tres fármacos a dosis óptimas, uno diurético. Se confirma apego y monitoreo de 24 horas, y se agrega espironolactona."],["¿Qué antihipertensivo se usa en el embarazo?","Alfametildopa, labetalol o nifedipino. Nunca inhibidores de la enzima convertidora ni antagonistas del receptor de angiotensina."],["¿Qué sugiere hipertensión con potasio bajo?","Hiperaldosteronismo primario."],["¿Cómo distingo urgencia de emergencia?","Ambas con 180 sobre 120 o más. La emergencia tiene daño agudo de órgano y requiere tratamiento intravenoso; la urgencia se baja con orales en 24 a 48 horas."],["¿Cuánta sal se permite?","Menos de 5 gramos al día, una cucharadita."]],"profundizar":{"harrison":[[277,"Hipertensión"]],"guias":[["Promoción, prevención, diagnóstico y tratamiento de la hipertensión arterial en el primer nivel de atención, GPC-IMSS-076-21, 2021 (sin enlace oficial por ahora; abajo la versión 2014)",""],["Diagnóstico y tratamiento de las crisis hipertensivas en adultos en los tres niveles de atención, GPC-SS-155-20, 2020 (sin enlace oficial por ahora)",""],["Diagnóstico y tratamiento de la hipertensión arterial en el primer nivel de atención, IMSS-076-08, actualización 2014","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/076GRR.pdf"],["Protocolo de Atención Integral: hipertensión arterial sistémica, Instituto Mexicano del Seguro Social, 2022","https://revistamedica.imss.gob.mx/index.php/revista_medica/article/download/4424/4319"]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Cardiología, capítulo 14, páginas 140 a 147 del archivo.","Protocolo de Atención Integral: hipertensión arterial sistémica, Instituto Mexicano del Seguro Social, Revista Médica del IMSS 2022;60 Supl 1:S34-46.","Guía de Práctica Clínica de hipertensión arterial en el primer nivel de atención, Centro Nacional de Excelencia Tecnológica en Salud, 2021.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 277.","Fichas verificadas de losartán, enalapril y amlodipino en GCHE2 (etiquetas oficiales)."]},"endocrinologia-5":{"titulo":"Diabetes mellitus tipo 2 en la consulta","enfoque":"Enfoque de consulta de primer nivel: diagnóstico, metas, tratamiento escalonado y vigilancia de complicaciones en el adulto.","resumen":[{"h":"Lo esencial en 30 segundos","li":["La diabetes tipo 2 es hiperglucemia crónica por **resistencia a la insulina** más una **falla progresiva de la célula beta**; casi siempre se asocia a sobrepeso, obesidad abdominal y sedentarismo.","El diagnóstico exige **dos resultados alterados** (la misma prueba repetida o dos pruebas distintas), salvo glucosa al azar de 200 mg/dL o más con síntomas, que basta sola.","Meta para la mayoría: **hemoglobina glucosilada menor de 7%**; más laxa en adultos mayores frágiles o con hipoglucemias.","Primer fármaco: **metformina** junto con cambios de estilo de vida. Si hay enfermedad cardiovascular, insuficiencia cardiaca o enfermedad renal, agregar un **inhibidor del cotransportador sodio-glucosa tipo 2** o un **agonista del receptor del péptido similar al glucagón tipo 1**, sin importar la cifra de hemoglobina glucosilada.","Revisar y ajustar el tratamiento **cada 3 meses** si no está en metas: evitar la inercia terapéutica."]},{"h":"Diagnóstico","li":["Glucosa plasmática en ayuno de **126 mg/dL o más** (ayuno de al menos 8 horas).","Glucosa a las 2 horas de la curva de tolerancia oral con 75 g de glucosa de **200 mg/dL o más**.","Hemoglobina glucosilada de **6.5% o más**, con método certificado.","Glucosa al azar de **200 mg/dL o más con síntomas clásicos** (poliuria, polidipsia, polifagia, pérdida de peso) o crisis hiperglucémica: no requiere confirmación.","Si dos pruebas distintas no coinciden, se repite la que salió alterada; con resultados limítrofes, repetir en 3 a 6 meses.","La hemoglobina glucosilada no sirve en anemia de células falciformes, embarazo (segundo y tercer trimestre), hemodiálisis, transfusión o tratamiento con eritropoyetina: usar solo criterios de glucosa."]},{"h":"Prediabetes","li":["Glucosa alterada en ayuno: **100 a 125 mg/dL**.","Intolerancia a la glucosa: **140 a 199 mg/dL** a las 2 horas de la curva.","Hemoglobina glucosilada de **5.7 a 6.4%**.","Se vigila **cada año** y se tratan los factores de riesgo cardiovascular.","El protocolo del Instituto Mexicano del Seguro Social indica metformina en prediabetes en menores de 60 años, con índice de masa corporal mayor de 35 o con antecedente de diabetes gestacional."]},{"h":"A quién hacer tamizaje","li":["Todo adulto desde los **35 años**; antes si tiene sobrepeso (índice de masa corporal de 25 o más) y al menos un factor de riesgo.","Factores de riesgo: familiar de primer grado con diabetes, origen latino, hipertensión, enfermedad cardiovascular, colesterol de alta densidad menor de 35 o triglicéridos mayores de 250 mg/dL, síndrome de ovario poliquístico, sedentarismo, acantosis nigricans, antecedente de diabetes gestacional o de recién nacido de más de 4 kg.","Si el resultado es normal, repetir **cada 3 años**; mujeres con diabetes gestacional previa, al menos cada 3 años de por vida."]},{"h":"Metas de control","li":["Hemoglobina glucosilada: **menor de 7%** para la mayoría; **menor de 6.5%** en jóvenes, con poca evolución y sin riesgo de hipoglucemia; **menor de 8%** (hasta 8.5%) en adultos mayores frágiles, con hipoglucemias graves, poca expectativa de vida o complicaciones avanzadas.","Glucosa en ayuno o antes de comer: **80 a 130 mg/dL**. Glucosa 2 horas después de comer: **menor de 180 mg/dL**.","Presión arterial: **menor de 130/80 mmHg**.","Colesterol de baja densidad: muy alto riesgo menor de 70 mg/dL; alto riesgo menor de 100 mg/dL (protocolo del Instituto Mexicano del Seguro Social).","Peso: reducir **5 a 10%** si hay sobrepeso u obesidad."]},{"h":"Tratamiento no farmacológico","li":["Plan de alimentación con nutrición: reducir azúcares simples y bebidas azucaradas, porciones con el plato del bien comer.","Actividad física: al menos **150 minutos por semana** de ejercicio aeróbico moderado, repartidos en 3 o más días, más ejercicios de fuerza 2 veces por semana.","Dejar de fumar; educación en diabetes y autocuidado de pies."]},{"h":"Metformina: el primer fármaco","li":["Inicio: **500 mg cada 12 horas** u 850 mg una vez al día **con alimentos**; subir 500 mg por semana. Máximo **2,550 mg al día**.","Efectos adversos: digestivos (náusea, diarrea, distensión) al inicio; con el uso prolongado, **deficiencia de vitamina B12**; acidosis láctica es rara.","Función renal: **contraindicada con filtración glomerular menor de 30**; con 30 a 45 no iniciar; suspender antes de estudios con contraste yodado.","Si no se tolera: presentación de liberación prolongada o cambiar a un inhibidor de la dipeptidil peptidasa 4."]},{"h":"Segundo fármaco: según el perfil del paciente","li":["Enfermedad cardiovascular aterosclerótica o alto riesgo cardiovascular: **agonista del receptor del péptido similar al glucagón tipo 1** (liraglutida, dulaglutida, semaglutida) o **inhibidor del cotransportador sodio-glucosa tipo 2** (empagliflozina, dapagliflozina, canagliflozina) con beneficio demostrado.","Insuficiencia cardiaca o enfermedad renal crónica con albuminuria: **inhibidor del cotransportador sodio-glucosa tipo 2** de preferencia.","Necesidad de bajar peso: agonista del péptido similar al glucagón tipo 1 o inhibidor del cotransportador sodio-glucosa tipo 2.","Riesgo de hipoglucemia o adulto mayor frágil: **inhibidor de la dipeptidil peptidasa 4** (sitagliptina, linagliptina; esta última sin ajuste renal).","Bajo costo: **sulfonilurea** (glibenclamida, glimepirida): causa hipoglucemia y aumento de peso; el protocolo mexicano la reserva para menores de 65 años, filtración mayor de 60 e índice de masa corporal menor de 30.","**No combinar** inhibidor de la dipeptidil peptidasa 4 con agonista del péptido similar al glucagón tipo 1.","Iniciar con **dos fármacos** si la hemoglobina glucosilada está 1.5 puntos o más por arriba de la meta."]},{"h":"Efectos adversos que más se preguntan","li":["Inhibidores del cotransportador sodio-glucosa tipo 2: **infecciones genitales**, infección urinaria, hipovolemia y **cetoacidosis euglucémica**.","Agonistas del péptido similar al glucagón tipo 1: náusea y vómito; suspender si hay pancreatitis; contraindicados con antecedente personal o familiar de carcinoma medular de tiroides o neoplasia endocrina múltiple tipo 2.","Pioglitazona: retención de líquidos y **empeora la insuficiencia cardiaca**; aumenta peso y riesgo de fracturas.","Sulfonilureas: **hipoglucemia** (sobre todo en adultos mayores y con falla renal) y aumento de peso."]},{"h":"Cuándo iniciar insulina","li":["Síntomas de catabolismo (pérdida de peso, cetosis), **hemoglobina glucosilada mayor de 10%** o **glucosa de 300 mg/dL o más**: insulina desde el inicio.","Protocolo del Instituto Mexicano del Seguro Social: hemoglobina glucosilada de 9% o más o glucosa mayor de 260 mg/dL; falla a triple terapia oral; embarazo; cirugía o imposibilidad para la vía oral.","Inicio con insulina basal: **10 unidades al día o 0.1 a 0.2 unidades por kilo** (glargina en la noche, o NPH con dos tercios en la mañana y un tercio en la noche).","Ajuste de glargina según el promedio de glucosa en ayuno, cada 7 días: 130 a 150 mg/dL, más 1 unidad; 150 a 179, más 2; 180 o más, más 3; menor de 80, menos 2.","Al iniciar insulina se suspenden sulfonilureas y pioglitazona; la metformina se mantiene."]},{"h":"Hipoglucemia","li":["Glucosa **menor de 70 mg/dL**. Síntomas adrenérgicos (temblor, sudoración, palpitaciones) y neuroglucopénicos (confusión, convulsiones).","Paciente consciente: **regla 15-15**: 15 g de azúcar de absorción rápida (medio vaso de jugo o refresco normal), medir a los 15 minutos y repetir si sigue baja.","Inconsciente: glucagón intramuscular o glucosa intravenosa al 50%.","Los betabloqueadores pueden **ocultar** los síntomas adrenérgicos."]},{"h":"Complicaciones: qué revisar y cada cuándo","li":["**Pies en cada consulta**; exploración completa cada año con **monofilamento de 10 g** y diapasón de 128 Hz (más seguido si hay riesgo).","**Fondo de ojo cada año** desde el diagnóstico.","**Cociente albúmina/creatinina en orina y filtración glomerular cada año**; albuminuria de 30 mg/g o más, confirmada en 2 de 3 muestras en 3 a 6 meses.","Perfil de lípidos al menos cada año (el protocolo mexicano lo pide cada 6 meses).","Hemoglobina glucosilada cada 3 meses si no está en metas y cada 6 meses si está controlada.","Estatina de intensidad moderada en diabéticos de 40 a 75 años; de alta intensidad si ya hay enfermedad cardiovascular."]},{"h":"Cuándo referir","li":["**Urgencias**: cetoacidosis diabética o estado hiperglucémico hiperosmolar, hipoglucemia grave, pie diabético infectado o con isquemia.","Nefrología: albuminuria mayor de 300 mg/g o filtración que cae rápido.","Medicina interna o endocrinología: falla a triple terapia, necesidad de esquema intensivo de insulina, sospecha de diabetes autoinmune del adulto o monogénica.","Oftalmología: cualquier alteración en el fondo de ojo."]}],"perlas":["La glucosa al azar de 200 mg/dL o más con síntomas **no se confirma**; todo lo demás sí.","Metformina se **suspende** con filtración menor de 30 y antes de contraste yodado.","Diabetes con insuficiencia cardiaca o enfermedad renal: **inhibidor del cotransportador sodio-glucosa tipo 2** aunque la hemoglobina glucosilada esté en meta.","Pioglitazona **contraindicada** en insuficiencia cardiaca.","Glucosuria y prurito genital en paciente con dapagliflozina: es efecto del fármaco (candidosis), no descontrol.","El monofilamento de 10 g detecta pérdida de la sensibilidad protectora: es el estudio clave del pie en primer nivel."],"mexico":["El Manual CTO sigue a la Asociación Americana de Diabetes. En México rigen la Guía de Práctica Clínica GPC-IMSS-718-18 (actualización 2018) y el Protocolo de Atención Integral de diabetes del Instituto Mexicano del Seguro Social (2022).","El protocolo mexicano define metas por grupos: menor de 7% en menores de 65 años sin daño renal; menor de 7.5% en mayores de 65 independientes o enfermedad renal 3; menor de 8% en frágiles o enfermedad renal 4; menor de 8.5% en enfermedad renal 5 o enfermedad terminal.","En el Instituto Mexicano del Seguro Social, los agonistas del péptido similar al glucagón tipo 1 se reservan a casos selectos con índice de masa corporal mayor de 35 y los prescribe endocrinología.","Los datos de epidemiología del CTO son de España; en México la diabetes es una de las primeras causas de muerte."],"preguntas":[{"c":"Hombre de 45 años, asintomático, con índice de masa corporal de 31. Glucosa en ayuno de 132 mg/dL en un estudio de rutina.","p":"¿Cuál es la conducta correcta?","o":["Diagnosticar diabetes e iniciar metformina","Repetir la glucosa en ayuno u otra prueba diagnóstica para confirmar","Solicitar curva de tolerancia con 100 g de glucosa","Diagnosticar prediabetes y citar en un año"],"r":1,"e":"En un paciente asintomático, un solo valor alterado no basta: se confirma con una segunda prueba (la misma repetida o una distinta). Solo la glucosa al azar de 200 mg/dL o más con síntomas no requiere confirmación. La curva de 100 g es para diabetes gestacional.","f":"Manual CTO, Endocrinología, capítulo 5, criterios diagnósticos (tabla 5.1)."},{"c":"Mujer de 38 años con poliuria, polidipsia y pérdida de 5 kg en dos meses. Glucosa capilar al azar de 286 mg/dL, confirmada en sangre venosa.","p":"¿Qué se concluye?","o":["Requiere una segunda glucosa en ayuno para el diagnóstico","Tiene diabetes; no requiere más pruebas para el diagnóstico","Requiere hemoglobina glucosilada antes de diagnosticar","Requiere curva de tolerancia oral a la glucosa"],"r":1,"e":"Glucosa plasmática al azar de 200 mg/dL o más con síntomas clásicos de hiperglucemia establece el diagnóstico sin confirmación. La pérdida de peso sugiere catabolismo: valorar insulina desde el inicio.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente de 50 años con glucosa en ayuno de 112 mg/dL y hemoglobina glucosilada de 6.0%.","p":"¿Cuál es su diagnóstico?","o":["Diabetes tipo 2","Normoglucemia","Prediabetes","Intolerancia a la glucosa confirmada"],"r":2,"e":"Glucosa en ayuno de 100 a 125 mg/dL y hemoglobina glucosilada de 5.7 a 6.4% corresponden a prediabetes. La intolerancia a la glucosa solo se define con la curva a las 2 horas (140 a 199 mg/dL).","f":"Manual CTO, Endocrinología, capítulo 5, figura 5.1."},{"c":"Mujer de 29 años con anemia de células falciformes. Su hemoglobina glucosilada es de 5.2% pero tiene glucosas en ayuno de 140 y 138 mg/dL en días distintos.","p":"¿Qué se concluye?","o":["No tiene diabetes porque la hemoglobina glucosilada es normal","Tiene diabetes; la hemoglobina glucosilada no es confiable en su caso","Debe repetirse la hemoglobina glucosilada en 3 meses","Debe hacerse curva con 100 g"],"r":1,"e":"En anemia de células falciformes, embarazo, hemodiálisis o uso de eritropoyetina la hemoglobina glucosilada no es válida; se usan solo criterios de glucosa. Dos glucosas en ayuno de 126 o más confirman diabetes.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Hombre de 55 años recién diagnosticado con diabetes tipo 2. Hemoglobina glucosilada de 7.8%, filtración glomerular de 85, sin enfermedad cardiovascular.","p":"¿Cuál es el tratamiento farmacológico inicial de elección?","o":["Glibenclamida","Metformina con cambios en el estilo de vida","Insulina NPH","Pioglitazona"],"r":1,"e":"La metformina, junto con dieta y ejercicio, es la primera línea en ausencia de contraindicaciones. Las sulfonilureas causan hipoglucemia y aumento de peso; la insulina se reserva para hiperglucemia grave o catabolismo.","f":"Manual CTO, Endocrinología, capítulo 5, figura 5.11; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social, 2022."},{"c":"Paciente diabético con metformina 850 mg cada 12 horas. Su filtración glomerular bajó a 24 mL/min.","p":"¿Qué haces con la metformina?","o":["Mantener la dosis","Reducir a 500 mg al día","Suspenderla","Cambiar a liberación prolongada"],"r":2,"e":"La metformina está contraindicada con filtración glomerular menor de 30 por el riesgo de acidosis láctica. Con 30 a 45 no se inicia y, si ya la toma, se valora reducir la dosis. Alternativas: inhibidor de la dipeptidil peptidasa 4 o insulina.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.18; ficha de metformina de GCHE2."},{"c":"Hombre de 62 años con diabetes tipo 2 e infarto de miocardio hace un año. Toma metformina y su hemoglobina glucosilada es de 6.8%.","p":"¿Qué conducta es la más adecuada?","o":["Continuar igual porque está en meta","Agregar un inhibidor del cotransportador sodio-glucosa tipo 2 o un agonista del péptido similar al glucagón tipo 1 con beneficio cardiovascular","Agregar glibenclamida","Agregar pioglitazona"],"r":1,"e":"Con enfermedad cardiovascular aterosclerótica establecida se recomienda un fármaco con beneficio cardiovascular demostrado independientemente de la hemoglobina glucosilada.","f":"Manual CTO, Endocrinología, capítulo 5, algoritmo de la Asociación Americana de Diabetes."},{"c":"Mujer de 68 años con diabetes tipo 2 e insuficiencia cardiaca con fracción de expulsión de 35%. Toma metformina.","p":"¿Qué segundo fármaco prefieres?","o":["Pioglitazona","Dapagliflozina","Glimepirida","Acarbosa"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 reducen hospitalizaciones por insuficiencia cardiaca. La pioglitazona está contraindicada en insuficiencia cardiaca porque causa retención de líquidos.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente con diabetes tipo 2 que inició empagliflozina hace 3 semanas. Acude por prurito y flujo vaginal blanco grumoso.","p":"¿Cuál es la explicación más probable?","o":["Descontrol glucémico grave","Candidosis vulvovaginal favorecida por la glucosuria del fármaco","Reacción alérgica al fármaco","Infección por Trichomonas por contacto sexual"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 producen glucosuria, lo que favorece infecciones genitales micóticas e infecciones urinarias.","f":"Manual CTO, Endocrinología, capítulo 5, efectos adversos de inhibidores del cotransportador sodio-glucosa tipo 2."},{"c":"Paciente de 50 años con diabetes tipo 2, tratado con dapagliflozina. Llega con náusea, dolor abdominal y respiración profunda. Glucosa de 210 mg/dL, pH de 7.18 y cetonas positivas.","p":"¿Qué complicación presenta?","o":["Estado hiperglucémico hiperosmolar","Cetoacidosis diabética euglucémica asociada al fármaco","Acidosis láctica por metformina","Gastroenteritis aguda"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 pueden causar cetoacidosis con glucosa casi normal. Se suspende el fármaco y se refiere a urgencias.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Hombre de 48 años con diabetes de 6 años de evolución, con metformina y sitagliptina. Su médico quiere agregar liraglutida.","p":"¿Qué error hay en este plan?","o":["Ninguno, es una combinación recomendada","No se debe combinar un inhibidor de la dipeptidil peptidasa 4 con un agonista del péptido similar al glucagón tipo 1","La liraglutida está contraindicada con metformina","La liraglutida produce hipoglucemia grave"],"r":1,"e":"Ambos actúan sobre la misma vía de las incretinas; combinarlos no agrega beneficio. Si se inicia el agonista del péptido similar al glucagón tipo 1, se suspende el inhibidor de la dipeptidil peptidasa 4.","f":"Manual CTO, Endocrinología, capítulo 5, figura 5.11; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Mujer de 44 años con diabetes tipo 2 y antecedente familiar de carcinoma medular de tiroides.","p":"¿Qué fármaco está contraindicado?","o":["Metformina","Semaglutida","Linagliptina","Empagliflozina"],"r":1,"e":"Los agonistas del péptido similar al glucagón tipo 1 están contraindicados con antecedente personal o familiar de carcinoma medular de tiroides o neoplasia endocrina múltiple tipo 2.","f":"Harrison, 21.ª edición, capítulo 404; etiquetas oficiales de los agonistas del péptido similar al glucagón tipo 1."},{"c":"Paciente de 58 años con diabetes tipo 2, con metformina y glimepirida. Hemoglobina glucosilada de 11.2% y glucosa en ayuno de 310 mg/dL, con pérdida de peso.","p":"¿Cuál es la conducta más adecuada?","o":["Agregar sitagliptina","Iniciar insulina basal","Aumentar la glimepirida al doble","Agregar acarbosa"],"r":1,"e":"Hemoglobina glucosilada mayor de 10%, glucosa de 300 mg/dL o más o datos de catabolismo son indicación de insulina.","f":"Manual CTO, Endocrinología, capítulo 5; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Hombre de 70 kg inicia insulina glargina.","p":"¿Cuál es una dosis inicial adecuada?","o":["0.5 unidades por kilo (35 unidades)","10 unidades al día o 0.1 a 0.2 unidades por kilo","1 unidad por kilo (70 unidades)","2 unidades al día"],"r":1,"e":"La insulina basal se inicia con 10 unidades al día o 0.1 a 0.2 unidades por kilo y se ajusta según la glucosa en ayuno cada semana.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social, 2022."},{"c":"Paciente con insulina glargina 14 unidades. El promedio de sus glucosas en ayuno de la última semana es de 165 mg/dL.","p":"¿Cómo ajustas la dosis?","o":["Bajar 2 unidades","Subir 2 unidades","Subir 6 unidades","Dejar igual"],"r":1,"e":"Según el protocolo mexicano: glucosa en ayuno de 150 a 179 mg/dL, subir 2 unidades; 130 a 150, subir 1; 180 o más, subir 3; menor de 80, bajar 2.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social, 2022."},{"c":"Mujer de 82 años, frágil, con caídas recientes y diabetes tipo 2 de larga evolución. Hemoglobina glucosilada de 7.7%.","p":"¿Qué meta de hemoglobina glucosilada es apropiada?","o":["Menor de 6.5%","Menor de 7%","Menor de 8 a 8.5%, evitando hipoglucemias","No importa la meta en adultos mayores"],"r":2,"e":"En adultos mayores frágiles, con poca expectativa de vida o riesgo de hipoglucemia, se aceptan metas más laxas; su 7.7% ya es aceptable y no se debe intensificar.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.20; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Paciente diabético en consulta de control.","p":"¿Cuál es la meta de glucosa en ayuno para la mayoría de los adultos?","o":["70 a 100 mg/dL","80 a 130 mg/dL","130 a 180 mg/dL","Menor de 200 mg/dL"],"r":1,"e":"Meta en ayuno o antes de comer: 80 a 130 mg/dL; después de comer, menor de 180 mg/dL.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.20."},{"c":"Paciente con diabetes tipo 2 e hipertensión.","p":"¿Cuál es la meta de presión arterial que se recomienda?","o":["Menor de 150/90 mmHg","Menor de 140/90 mmHg en todos los casos","Menor de 130/80 mmHg","Menor de 110/70 mmHg"],"r":2,"e":"En diabéticos se recomienda presión menor de 130/80 mmHg si se tolera.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 60 años con diabetes de 10 años de evolución. Refiere ardor en ambos pies de predominio nocturno.","p":"¿Qué estudio es clave en primer nivel para identificar riesgo de úlcera?","o":["Radiografía de pies","Exploración con monofilamento de 10 g","Electromiografía","Resonancia magnética"],"r":1,"e":"El monofilamento de Semmes-Weinstein de 10 g detecta la pérdida de sensibilidad protectora, principal factor de riesgo de úlcera. Se complementa con diapasón de 128 Hz y revisión de pulsos.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente diabético con cociente albúmina/creatinina de 85 mg/g en una muestra.","p":"¿Qué haces?","o":["Diagnosticar nefropatía diabética de inmediato","Confirmar con otras muestras: debe salir alterado en 2 de 3 en 3 a 6 meses","Suspender la metformina","Referir a nefrología de inmediato"],"r":1,"e":"La albuminuria se confirma en 2 de 3 determinaciones en 3 a 6 meses, porque el ejercicio, la fiebre o la infección urinaria la elevan transitoriamente. La referencia a nefrología es con más de 300 mg/g o caída rápida de la filtración.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Paciente diabético con albuminuria persistente e hipertensión.","p":"¿Qué grupo de antihipertensivos prefieres?","o":["Betabloqueadores","Inhibidores de la enzima convertidora de angiotensina o antagonistas del receptor de angiotensina II","Diuréticos de asa","Alfabloqueadores"],"r":1,"e":"Los inhibidores de la enzima convertidora de angiotensina y los antagonistas del receptor de angiotensina II reducen la albuminuria y retrasan la progresión de la nefropatía diabética. No se combinan entre sí.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente con diabetes tipo 2 recién diagnosticada.","p":"¿Cuándo debe hacerse el primer fondo de ojo?","o":["A los 5 años del diagnóstico","Al momento del diagnóstico y después cada año","Solo si tiene visión borrosa","Solo si la hemoglobina glucosilada es mayor de 9%"],"r":1,"e":"En diabetes tipo 2 la retinopatía puede existir desde el diagnóstico porque la enfermedad lleva años sin detectarse. Se revisa al diagnóstico y cada año.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente con glibenclamida que llega con sudoración, temblor y confusión leve, pero puede tragar. Glucosa capilar de 52 mg/dL.","p":"¿Cuál es el tratamiento inmediato?","o":["Insulina rápida","15 g de azúcar de absorción rápida y repetir glucosa en 15 minutos","Glucagón intravenoso","Observar sin tratamiento"],"r":1,"e":"En el paciente consciente se aplica la regla 15-15. Las hipoglucemias por sulfonilurea pueden ser prolongadas: vigilar varias horas y revalorar el fármaco.","f":"Manual CTO, Endocrinología, capítulo 5, hipoglucemia."},{"c":"Paciente diabético con metformina desde hace 8 años refiere parestesias en pies y tiene anemia macrocítica.","p":"¿Qué debes descartar?","o":["Deficiencia de hierro","Deficiencia de vitamina B12 por uso prolongado de metformina","Hipotiroidismo por metformina","Intoxicación por metformina"],"r":1,"e":"El uso prolongado de metformina reduce la absorción de vitamina B12, lo que causa anemia megaloblástica y neuropatía, que puede confundirse con neuropatía diabética.","f":"Harrison, 21.ª edición, capítulo 404."},{"c":"Mujer de 34 años con índice de masa corporal de 28 y diabetes gestacional en su embarazo previo. Su curva posparto fue normal.","p":"¿Cada cuánto se debe repetir el tamizaje de diabetes?","o":["Nunca más","Al menos cada 3 años de por vida","Solo en un próximo embarazo","Cada 10 años"],"r":1,"e":"Las mujeres con antecedente de diabetes gestacional tienen alto riesgo de diabetes tipo 2 y deben tamizarse al menos cada 3 años de por vida.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.2."},{"c":"Hombre de 30 años, asintomático, con índice de masa corporal de 24 y sin factores de riesgo.","p":"¿A qué edad inicia el tamizaje de diabetes según la Asociación Americana de Diabetes?","o":["18 años","35 años","45 años","60 años"],"r":1,"e":"El tamizaje universal inicia a los 35 años; antes si hay sobrepeso con al menos un factor de riesgo. Con resultado normal, repetir cada 3 años.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.2."},{"c":"Paciente de 66 años, con diabetes y filtración glomerular de 40, con riesgo de hipoglucemia. Toma metformina a dosis reducida.","p":"¿Qué segundo fármaco es más seguro?","o":["Glibenclamida","Linagliptina","Glimepirida a dosis alta","Clorpropamida"],"r":1,"e":"Los inhibidores de la dipeptidil peptidasa 4 tienen bajo riesgo de hipoglucemia; la linagliptina no requiere ajuste renal. Las sulfonilureas se acumulan en falla renal y causan hipoglucemias graves.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.18; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Paciente con diabetes tipo 2 y obesidad (índice de masa corporal de 36), con metformina y hemoglobina glucosilada de 8.1%. Desea bajar de peso.","p":"¿Qué familia de fármacos favorece más la pérdida de peso?","o":["Sulfonilureas","Agonistas del receptor del péptido similar al glucagón tipo 1","Pioglitazona","Insulina"],"r":1,"e":"Los agonistas del péptido similar al glucagón tipo 1 producen la mayor pérdida de peso; los inhibidores del cotransportador sodio-glucosa tipo 2 también la favorecen. Sulfonilureas, pioglitazona e insulina aumentan el peso.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Diabético de 52 años sin enfermedad cardiovascular, con colesterol de baja densidad de 118 mg/dL.","p":"¿Qué recomiendas para su riesgo cardiovascular?","o":["Ningún tratamiento hasta que el colesterol pase de 190 mg/dL","Estatina de intensidad moderada","Aspirina diaria como prevención primaria de rutina","Fibrato como primera elección"],"r":1,"e":"En diabéticos de 40 a 75 años se recomienda estatina de intensidad moderada aunque no tengan enfermedad cardiovascular. La aspirina en prevención primaria no es de rutina por el riesgo de sangrado.","f":"Asociación Americana de Diabetes, estándares de atención; Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente diabético con hemoglobina glucosilada de 9.5% a pesar de metformina a dosis máxima. Lleva 8 meses igual.","p":"¿Qué concepto describe esta situación?","o":["Diabetes resistente","Inercia terapéutica","Seudohipoglucemia","Fenómeno del alba"],"r":1,"e":"La inercia terapéutica es no intensificar el tratamiento pese a no alcanzar metas. El tratamiento debe revisarse y ajustarse cada 3 meses.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Endocrinología, capítulo 5."}],"audio":[["¿Cuáles son los cuatro criterios diagnósticos de diabetes?","Glucosa en ayuno de 126 o más; curva de tolerancia a las 2 horas de 200 o más; hemoglobina glucosilada de 6.5% o más; y glucosa al azar de 200 o más con síntomas, que es la única que no se confirma."],["¿Qué cifras definen prediabetes?","Glucosa en ayuno de 100 a 125, curva a las 2 horas de 140 a 199, o hemoglobina glucosilada de 5.7 a 6.4%."],["¿Desde qué edad se hace tamizaje?","Desde los 35 años, o antes si hay sobrepeso con un factor de riesgo. Si es normal, cada 3 años."],["¿Cuál es la meta de hemoglobina glucosilada?","Menor de 7% para la mayoría; menor de 6.5% en jóvenes sin riesgo de hipoglucemia; menor de 8% en adultos mayores frágiles."],["¿Cuál es el primer fármaco y cómo se inicia?","Metformina, 500 miligramos cada 12 horas con alimentos, subiendo cada semana hasta un máximo de 2,550 miligramos al día."],["¿Cuándo se suspende la metformina?","Con filtración glomerular menor de 30 y antes de estudios con contraste yodado."],["¿Qué agrego si hay enfermedad cardiovascular, insuficiencia cardiaca o enfermedad renal?","Un inhibidor del cotransportador sodio-glucosa tipo 2, o un agonista del péptido similar al glucagón tipo 1 si hay enfermedad aterosclerótica, aunque la hemoglobina glucosilada esté en meta."],["¿Qué efecto adverso típico tienen las gliflozinas?","Infecciones genitales micóticas, infección urinaria y cetoacidosis euglucémica."],["¿Qué antidiabético está contraindicado en insuficiencia cardiaca?","La pioglitazona, porque retiene líquidos."],["¿Cuándo se inicia insulina?","Con catabolismo, hemoglobina glucosilada mayor de 10% o glucosa de 300 o más. Se inicia basal con 10 unidades o 0.1 a 0.2 unidades por kilo."],["¿Cómo se trata una hipoglucemia en el paciente consciente?","Regla 15-15: 15 gramos de azúcar rápida y medir de nuevo a los 15 minutos."],["¿Qué se revisa cada año?","Fondo de ojo, cociente albúmina-creatinina con filtración glomerular, pie completo con monofilamento de 10 gramos y perfil de lípidos."],["¿Qué dos familias no se combinan?","Inhibidores de la dipeptidil peptidasa 4 con agonistas del péptido similar al glucagón tipo 1."]],"profundizar":{"harrison":[[403,"Diabetes mellitus: diagnóstico, clasificación y fisiopatología"],[404,"Diabetes mellitus: tratamiento"],[405,"Diabetes mellitus: complicaciones"]],"guias":[["Diagnóstico y tratamiento farmacológico de la diabetes mellitus tipo 2 en el primer nivel de atención, GPC-IMSS-718-18, actualización 2018","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/718GER.pdf"],["Protocolo de Atención Integral: prevención, diagnóstico y tratamiento de diabetes mellitus 2, Instituto Mexicano del Seguro Social, 2022","https://revistamedica.imss.gob.mx/index.php/revista_medica/article/download/4200/4317/29125"]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Endocrinología, capítulo 5, páginas 99 a 126 del archivo.","Guía de Práctica Clínica GPC-IMSS-718-18, actualización 2018.","Protocolo de Atención Integral de diabetes mellitus 2, Instituto Mexicano del Seguro Social, Revista Médica del IMSS 2022;60 Supl 1:S4-18.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulos 403 a 405.","Ficha verificada de metformina en GCHE2 (etiqueta oficial)."]},"enfermedades-infecciosas-6":{"titulo":"Infecciones respiratorias agudas altas en la consulta","enfoque":"Enfoque de consulta de primer nivel en niños y adultos: resfriado común, faringoamigdalitis, otitis media aguda y rinosinusitis aguda. Cuándo sí y cuándo no dar antibiótico, y cuándo referir. La neumonía se estudia en su propio tema.","resumen":[{"h":"Lo esencial en 30 segundos","li":["La mayoría son **virales**: el **rinovirus** es la causa más frecuente del resfriado a cualquier edad.","El antibiótico se reserva para: **faringoamigdalitis estreptocócica**, **otitis media aguda** que lo amerite y **rinosinusitis bacteriana** con criterios.","El moco verde o amarillo **no** indica infección bacteriana.","En **menores de 6 años no** se usan antitusivos ni antigripales.","Buscar siempre **datos de alarma** y signos de neumonía: respiración rápida, tiraje, saturación baja."]},{"h":"Resfriado común (rinofaringitis)","li":["Rinorrea, congestión, estornudos, dolor faríngeo leve, tos y febrícula; en niños, irritabilidad.","Dura de 5 a 10 días y hasta **14 días**; la tos puede durar más.","Tratamiento **sintomático**: paracetamol (niños 10 a 15 mg por kilo cada 4 a 6 horas; máximo 75 mg por kilo al día) o ibuprofeno; líquidos; lavados nasales con solución salina; **miel en mayores de 1 año** para la tos.","La Guía de Práctica Clínica mexicana de niños **no recomienda** antitusivos, descongestionantes, bromuro de ipratropio, vitamina C ni zinc.","**No dar antibiótico**: no acorta el cuadro ni previene complicaciones."]},{"h":"Faringoamigdalitis: ¿viral o estreptocócica?","li":["Viral en la mayoría: hasta dos terceras partes en niños y alrededor de **90% en adultos**.","Sugiere virus: **tos, rinorrea, conjuntivitis, disfonía, aftas**, diarrea.","Sugiere **estreptococo beta hemolítico del grupo A**: inicio brusco, fiebre alta, **exudado amigdalino**, **adenopatía cervical anterior dolorosa**, **ausencia de tos**, petequias en paladar; edad típica de 5 a 15 años.","Escarlatina: además exantema áspero en papel de lija y lengua de fresa."]},{"h":"Criterios de Centor modificados por McIsaac","li":["Un punto por cada uno: fiebre mayor de 38 °C, ausencia de tos, adenopatía cervical anterior dolorosa, exudado o crecimiento amigdalino.","Edad: **3 a 14 años, más 1**; 15 a 44 años, 0; **45 años o más, menos 1**.","**0 a 1 punto**: probablemente viral; sin prueba ni antibiótico.","**2 a 3 puntos**: prueba rápida de antígeno o cultivo; antibiótico si es positivo.","**4 a 5 puntos**: alta probabilidad; prueba rápida si existe, o tratamiento empírico donde no hay prueba.","La prueba rápida tiene sensibilidad cercana a 75% y especificidad de 95%: en niños, si sale negativa, se confirma con cultivo."]},{"h":"Tratamiento de la faringoamigdalitis estreptocócica","li":["**Penicilina G benzatínica** intramuscular en **dosis única**: 1,200,000 unidades si pesa 27 kg o más; **600,000 unidades si pesa menos de 27 kg**. Útil si se duda del apego.","**Penicilina V** oral por **10 días** (adulto: 500 mg cada 6 horas o 1,000 mg cada 12 horas, según el Harrison).","**Amoxicilina** por **10 días**: niños 50 mg por kilo al día en una o dos tomas (máximo 1,000 mg al día); adultos 500 mg cada 12 horas o 1,000 mg al día.","Alergia leve a penicilina: cefalexina 10 días. Alergia grave: clindamicina 10 días, o macrólido (azitromicina, en niños 12 mg por kilo al día por 5 días, máximo 500 mg).","Siempre analgésico y antipirético; mejora en 48 a 72 horas. Si no mejora, revalorar para descartar absceso.","Tratar dentro de los primeros **9 días** previene la **fiebre reumática**, pero **no** la glomerulonefritis posestreptocócica."]},{"h":"Complicaciones de la faringoamigdalitis","li":["**Absceso periamigdalino**: odinofagia intensa unilateral, **trismus**, voz apagada ('de papa caliente'), sialorrea, **úvula desviada al lado contrario**. Referir para drenaje.","No supurativas: fiebre reumática (2 a 4 semanas después) y glomerulonefritis posestreptocócica (1 a 3 semanas después).","Mononucleosis infecciosa: adolescente con faringitis exudativa, **adenopatía cervical posterior**, esplenomegalia y fatiga; con **amoxicilina aparece exantema**. Evitar deportes de contacto por riesgo de rotura de bazo.","Referencia urgente: estridor, sialorrea, dificultad para respirar o tragar, sospecha de epiglotitis o absceso."]},{"h":"Otitis media aguda","li":["Pico entre los **6 meses y 3 años**. Gérmenes: **neumococo**, Haemophilus influenzae no tipificable, Moraxella catarrhalis y estreptococo del grupo A.","Diagnóstico: inicio agudo con **membrana timpánica abombada**, que es el hallazgo clave, o **otorrea** de inicio reciente; otalgia, fiebre e irritabilidad. El tímpano solo enrojecido por llanto no basta.","**Antibiótico de inmediato**: otorrea, síntomas graves (otalgia de más de 48 horas o fiebre de 39 °C o más), **menores de 2 años con otitis bilateral** y menores de 6 meses.","Observación vigilada de 48 a 72 horas posible en niños de 6 a 23 meses con otitis unilateral no grave y en mayores de 2 años no graves, si se garantiza la revaloración.","Elección: **amoxicilina a dosis alta, 80 a 90 mg por kilo al día** en dos tomas (máximo 3 g al día).","Amoxicilina con ácido clavulánico si recibió amoxicilina en los últimos 30 días, si hay conjuntivitis purulenta (sugiere Haemophilus) o si no mejora en 48 a 72 horas; alternativa: ceftriaxona intramuscular por 3 días.","Duración: **10 días en menores de 2 años** o síntomas graves; 5 a 7 días de 2 a 5 años; 5 días en 6 años o más con cuadro leve o moderado.","Complicación a referir: **mastoiditis** (dolor, eritema y despegamiento del pabellón auricular)."]},{"h":"Rinosinusitis aguda","li":["Casi siempre viral. En adultos se afecta más el **seno maxilar**; en niños, el **etmoidal**.","Clínica: congestión, rinorrea purulenta, dolor facial que **empeora al agachar la cabeza**, dolor a la palpación de senos, hiposmia.","Sospechar bacteriana (cualquiera de tres): **síntomas por 10 días o más sin mejoría**; **inicio grave** (fiebre de 39 °C o más con rinorrea purulenta o dolor facial por 3 a 4 días); o **empeoramiento después de una mejoría inicial** (doble empeoramiento).","Gérmenes: neumococo, Haemophilus influenzae y Moraxella catarrhalis, igual que la otitis.","Adultos: **amoxicilina con ácido clavulánico 875/125 mg cada 12 horas por 5 a 7 días**; alternativa amoxicilina 875 mg cada 12 horas. Sintomático: lavados nasales salinos, analgésico, esteroide intranasal.","No se piden radiografías de rutina: el diagnóstico es clínico.","Referencia urgente: **edema o eritema periorbitario**, alteraciones visuales, cefalea intensa, signos meníngeos o alteración del estado de alerta."]},{"h":"Influenza","li":["Inicio brusco con fiebre alta, mialgias, cefalea y postración.","**Oseltamivir** en pacientes de alto riesgo (menores de 2 años, mayores de 65, embarazadas, enfermedades crónicas) o graves, de preferencia en las primeras 48 horas: adulto 75 mg cada 12 horas por 5 días; en niños, dosis por peso."]},{"h":"Datos de alarma y cuándo referir","li":["Respiración rápida para la edad (Organización Mundial de la Salud): **60 o más por minuto en menores de 2 meses, 50 o más de 2 a 11 meses, 40 o más de 1 a 4 años**; tiraje, quejido, cianosis o saturación baja: sospecha de neumonía.","Estridor en reposo, sialorrea, dificultad para tragar o respirar.","Alteraciones neurológicas, vómito persistente, disminución de la orina, exantema petequial o purpúrico.","Indicar a los padres regresar si: la fiebre dura más de 3 días, empeora o aparecen síntomas nuevos después de 3 a 5 días, o no mejora en 7 a 10 días.","Fiebre mayor de 39 °C, dolor torácico o síntomas por más de 14 días en adultos."]}],"perlas":["Resfriado y bronquitis aguda: **sin antibiótico**.","Centor de 0 a 1: **ni prueba ni antibiótico**.","Faringitis estreptocócica: **penicilina benzatínica dosis única** o penicilina V o amoxicilina por **10 días**.","Penicilina benzatínica: **600,000 unidades si pesa menos de 27 kg**; 1,200,000 si pesa más.","Exantema tras amoxicilina en adolescente con faringitis: **mononucleosis**.","Otitis media: el hallazgo clave es el **tímpano abombado**; amoxicilina a **80 a 90 mg por kilo al día**.","Sinusitis bacteriana: **10 días sin mejoría, inicio grave o doble empeoramiento**."],"mexico":["La Guía de Práctica Clínica IMSS-073-08 de faringoamigdalitis es de 2008 y propone penicilina compuesta seguida de penicilina procaínica, y un esquema de erradicación con penicilina benzatínica cada 21 días por 3 meses. El CTO y el Harrison recomiendan **penicilina benzatínica en dosis única o penicilina V o amoxicilina por 10 días**: usa estos esquemas, que son los actuales.","La misma guía mexicana propone eritromicina o trimetoprima con sulfametoxazol en alérgicos; el trimetoprima con sulfametoxazol **no** es adecuado para el estreptococo del grupo A. Usa cefalexina, clindamicina o un macrólido.","La Guía IMSS-062-08 (actualización 2016) de niños de 3 meses a 18 años recomienda paracetamol para la fiebre y **no usar** antitusivos, descongestionantes, bromuro de ipratropio, vitamina C ni zinc; antibiótico inmediato en otitis bilateral en menores de 2 años y en otitis con otorrea.","El CTO desaconseja macrólidos en España por resistencias del estreptococo; en México se usan como alternativa en alérgicos."],"preguntas":[{"c":"Niña de 4 años con 3 días de rinorrea hialina, estornudos, tos y temperatura de 37.8 °C. Come bien, frecuencia respiratoria de 28 por minuto, sin tiraje.","p":"¿Cuál es el manejo adecuado?","o":["Amoxicilina por 7 días","Paracetamol, líquidos y lavados nasales; sin antibiótico","Antitusivo con codeína","Antihistamínico con descongestionante"],"r":1,"e":"Es un resfriado común, de origen viral. El manejo es sintomático; en menores de 6 años no se usan antitusivos ni antigripales.","f":"Guía IMSS-062-08, actualización 2016; Harrison, 21.ª edición, capítulo 35."},{"c":"Madre de un niño de 3 años con resfriado de 5 días pide antibiótico porque el moco se volvió verde.","p":"¿Qué le explicas?","o":["El moco verde confirma infección bacteriana","El color del moco no distingue entre infección viral y bacteriana; no requiere antibiótico","Hay que iniciar amoxicilina con ácido clavulánico","Hay que tomar radiografía de senos"],"r":1,"e":"El moco purulento es parte de la evolución normal del resfriado viral. Se sospecha sinusitis bacteriana solo con más de 10 días sin mejoría, inicio grave o doble empeoramiento.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Lactante de 8 meses con resfriado.","p":"¿Qué remedio está contraindicado por su edad?","o":["Paracetamol","Miel para la tos","Lavados nasales con solución salina","Aspiración de secreciones con perilla"],"r":1,"e":"La miel no se da en menores de 1 año por riesgo de botulismo infantil; en mayores de 1 año puede aliviar la tos.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 9 años con fiebre de 39 °C, odinofagia de inicio brusco, amígdalas con exudado, adenopatías cervicales anteriores dolorosas y sin tos.","p":"¿Cuántos puntos de Centor modificados por McIsaac tiene y qué indica?","o":["2 puntos, probable virus","5 puntos, alta probabilidad de estreptococo","3 puntos, solo tratamiento sintomático","1 punto, sin estudios"],"r":1,"e":"Fiebre, exudado, adenopatía anterior dolorosa y ausencia de tos suman 4, más 1 por la edad de 3 a 14 años: 5 puntos, alta probabilidad de estreptococo del grupo A.","f":"Guía IMSS-062-08; Harrison, 21.ª edición, capítulo 35."},{"c":"Mujer de 30 años con odinofagia, rinorrea, tos, disfonía y conjuntivitis. Faringe eritematosa sin exudado.","p":"¿Qué conducta es adecuada?","o":["Penicilina benzatínica","Tratamiento sintomático; probable faringitis viral","Amoxicilina por 10 días","Cultivo faríngeo obligatorio"],"r":1,"e":"Tos, rinorrea, conjuntivitis y disfonía orientan a etiología viral. Con Centor bajo no se requiere prueba ni antibiótico.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6, tabla 6.1."},{"c":"Niño de 7 años con faringoamigdalitis y prueba rápida de estreptococo negativa, pero con 4 criterios clínicos.","p":"¿Cuál es el siguiente paso?","o":["Descartar estreptococo","Tomar cultivo faríngeo","Repetir la prueba rápida en una semana","Iniciar azitromicina"],"r":1,"e":"La prueba rápida tiene sensibilidad cercana a 75%; en niños, un resultado negativo se confirma con cultivo, que es el estándar de oro.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Niño de 6 años y 20 kg con faringoamigdalitis estreptocócica confirmada. La madre teme que no le dé completo el tratamiento oral.","p":"¿Qué tratamiento eliges?","o":["Penicilina G benzatínica 1,200,000 unidades intramuscular, dosis única","Penicilina G benzatínica 600,000 unidades intramuscular, dosis única","Amoxicilina por 3 días","Ceftriaxona por 10 días"],"r":1,"e":"La penicilina benzatínica en dosis única asegura el tratamiento: 600,000 unidades si pesa menos de 27 kg y 1,200,000 si pesa 27 kg o más.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6; esquema de dosificación por peso de la Asociación Americana del Corazón."},{"c":"Adolescente de 16 años con faringoamigdalitis estreptocócica confirmada, sin alergias.","p":"¿Cuál es la duración del tratamiento con penicilina V oral?","o":["3 días","5 días","10 días","21 días"],"r":2,"e":"La faringitis estreptocócica requiere 10 días de penicilina V o amoxicilina; los esquemas cortos fallan más.","f":"Harrison, 21.ª edición, capítulo 35, cuadro 35-5."},{"c":"Niño de 5 años y 18 kg con faringitis estreptocócica. Se elige amoxicilina oral.","p":"¿Cuál es la dosis adecuada?","o":["50 mg por kilo al día por 10 días, máximo 1,000 mg al día","90 mg por kilo al día por 3 días","20 mg por kilo al día por 5 días","1 g cada 8 horas por 10 días"],"r":0,"e":"Para faringitis estreptocócica en niños: amoxicilina 50 mg por kilo al día en una o dos tomas por 10 días, máximo 1,000 mg al día. La dosis de 80 a 90 mg por kilo es para otitis media.","f":"Sociedad de Enfermedades Infecciosas de América, guía de faringitis estreptocócica; Harrison, 21.ª edición, capítulo 35."},{"c":"Mujer de 25 años con faringitis estreptocócica y antecedente de anafilaxia con penicilina.","p":"¿Qué antibiótico es apropiado?","o":["Cefalexina","Clindamicina","Amoxicilina con ácido clavulánico","Trimetoprima con sulfametoxazol"],"r":1,"e":"Con alergia grave a penicilina se evitan los betalactámicos, incluidas las cefalosporinas. Opciones: clindamicina por 10 días o un macrólido. El trimetoprima con sulfametoxazol no erradica bien al estreptococo del grupo A.","f":"Harrison, 21.ª edición, capítulo 35, cuadro 35-5."},{"c":"Adolescente de 17 años con faringitis exudativa, fiebre, fatiga intensa, adenopatías cervicales posteriores y esplenomegalia. Le dieron amoxicilina y presentó exantema maculopapular.","p":"¿Cuál es el diagnóstico más probable?","o":["Alergia verdadera a la penicilina","Mononucleosis infecciosa por virus de Epstein-Barr","Escarlatina","Síndrome de Stevens-Johnson"],"r":1,"e":"La mononucleosis da faringitis con adenopatía posterior, esplenomegalia y fatiga; la amoxicilina desencadena un exantema característico que no indica alergia permanente.","f":"Manual CTO, Otorrinolaringología, capítulo 5; Harrison, 21.ª edición, capítulo 35."},{"c":"Paciente con mononucleosis infecciosa confirmada que juega fútbol americano.","p":"¿Qué recomendación es importante?","o":["Puede jugar en cuanto baje la fiebre","Evitar deportes de contacto por riesgo de rotura esplénica","Iniciar aciclovir","Tomar amoxicilina profiláctica"],"r":1,"e":"La esplenomegalia de la mononucleosis aumenta el riesgo de rotura de bazo con traumatismos; se evitan deportes de contacto por varias semanas.","f":"Harrison, 21.ª edición, capítulo 194."},{"c":"Hombre de 24 años con 5 días de faringitis que empeoró: odinofagia intensa del lado izquierdo, trismus, voz apagada y úvula desviada a la derecha.","p":"¿Cuál es el diagnóstico y la conducta?","o":["Faringitis viral; sintomáticos","Absceso periamigdalino; referir para drenaje y antibiótico","Mononucleosis; reposo","Epiglotitis; alta con antibiótico oral"],"r":1,"e":"Trismus, voz de papa caliente y desviación de la úvula al lado contrario son típicos del absceso periamigdalino, que requiere drenaje.","f":"Guía IMSS-073-08; Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Niño de 8 años con faringitis estreptocócica no tratada hace 3 semanas. Hoy presenta fiebre, artritis migratoria de rodillas y tobillos y un soplo nuevo.","p":"¿Qué complicación presenta?","o":["Glomerulonefritis posestreptocócica","Fiebre reumática","Artritis séptica","Púrpura de Henoch-Schönlein"],"r":1,"e":"La fiebre reumática aparece 2 a 4 semanas después de una faringitis estreptocócica; se previene si el antibiótico se da en los primeros 9 días.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Sobre la glomerulonefritis posestreptocócica.","p":"¿Qué afirmación es correcta?","o":["Se previene con el tratamiento antibiótico de la faringitis","No se previene con el tratamiento antibiótico de la faringitis","Solo ocurre después de infecciones de piel","Aparece en las primeras 24 horas"],"r":1,"e":"A diferencia de la fiebre reumática, la glomerulonefritis posestreptocócica no se previene con el tratamiento antibiótico de la faringitis.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 7 años con faringitis, fiebre, lengua de fresa y exantema áspero que inicia en cuello y pliegues.","p":"¿Cuál es el diagnóstico?","o":["Sarampión","Escarlatina","Exantema súbito","Enfermedad de Kawasaki confirmada"],"r":1,"e":"La escarlatina es una faringoamigdalitis por estreptococo del grupo A con exantema en papel de lija por toxinas; se trata igual que la faringitis estreptocócica.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Niño de 18 meses con fiebre de 38.5 °C e irritabilidad. En la otoscopia ambos tímpanos están abombados, opacos y eritematosos.","p":"¿Cuál es la conducta?","o":["Observación vigilada por 72 horas","Amoxicilina a dosis alta de inmediato","Gotas óticas con antibiótico","Referir a otorrinolaringología"],"r":1,"e":"En menores de 2 años con otitis media bilateral se indica antibiótico de inmediato; la primera elección es amoxicilina a 80 a 90 mg por kilo al día.","f":"Guía IMSS-062-08; Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 3 años con otitis media aguda unilateral, otalgia leve de 24 horas y temperatura de 38 °C. Los padres pueden regresar en 48 horas.","p":"¿Qué opción es válida?","o":["Observación vigilada de 48 a 72 horas con analgésico","Ceftriaxona intramuscular","Timpanocentesis","Amoxicilina con ácido clavulánico por 14 días"],"r":0,"e":"En mayores de 2 años con otitis no grave es válido observar 48 a 72 horas con analgesia, si se garantiza la revaloración; si no mejora, se inicia antibiótico.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niña de 2 años y 12 kg con otitis media aguda que amerita antibiótico; no recibió antibióticos el último mes.","p":"¿Qué dosis de amoxicilina indicas?","o":["Alrededor de 1,000 a 1,080 mg al día divididos cada 12 horas","250 mg al día","3,000 mg al día","500 mg una vez a la semana"],"r":0,"e":"Amoxicilina a dosis alta de 80 a 90 mg por kilo al día: con 12 kg son 960 a 1,080 mg al día, divididos cada 12 horas.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 4 años que tomó amoxicilina hace 3 semanas y hoy presenta otitis media aguda con conjuntivitis purulenta.","p":"¿Qué antibiótico eliges?","o":["Amoxicilina a dosis habitual","Amoxicilina con ácido clavulánico","Azitromicina por 1 día","Trimetoprima con sulfametoxazol"],"r":1,"e":"Si recibió amoxicilina en los últimos 30 días o hay conjuntivitis purulenta (sugiere Haemophilus influenzae productor de betalactamasa), se usa amoxicilina con ácido clavulánico.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño con otitis media aguda que tras 72 horas de amoxicilina persiste con fiebre y otalgia.","p":"¿Cuál es el siguiente paso?","o":["Continuar igual otros 7 días","Cambiar a amoxicilina con ácido clavulánico o ceftriaxona intramuscular por 3 días","Suspender antibiótico","Agregar descongestionante"],"r":1,"e":"La falta de mejoría en 48 a 72 horas obliga a cambiar a amoxicilina con clavulánico, cefalosporina de segunda o tercera generación o ceftriaxona intramuscular por 3 días.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 3 años con otitis media que ahora presenta fiebre, dolor y eritema retroauricular con pabellón auricular desplazado hacia adelante.","p":"¿Qué sospechas?","o":["Otitis externa","Mastoiditis aguda","Adenitis retroauricular por piojos","Celulitis facial"],"r":1,"e":"La mastoiditis es una complicación de la otitis media; da dolor, edema y eritema retroauricular con despegamiento del pabellón. Requiere referencia urgente.","f":"Manual CTO, Otorrinolaringología, capítulo 2."},{"c":"Sobre la otitis media aguda.","p":"¿Cuál es el germen más frecuente?","o":["Staphylococcus aureus","Streptococcus pneumoniae","Pseudomonas aeruginosa","Moraxella catarrhalis"],"r":1,"e":"El neumococo es el más frecuente, seguido de Haemophilus influenzae y Moraxella catarrhalis; los mismos de la sinusitis. Pseudomonas es típico de la otitis externa.","f":"Manual CTO, Otorrinolaringología, capítulo 2."},{"c":"Adulto de 35 años con rinorrea purulenta, congestión y dolor facial desde hace 4 días, sin fiebre, mejorando poco a poco.","p":"¿Qué indicas?","o":["Amoxicilina con ácido clavulánico por 10 días","Tratamiento sintomático: lavados salinos, analgésico y esteroide intranasal","Tomografía de senos","Levofloxacino"],"r":1,"e":"Es una rinosinusitis de pocos días, probablemente viral. El antibiótico se reserva para más de 10 días sin mejoría, inicio grave o doble empeoramiento.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Mujer de 40 años con resfriado que mejoraba, pero al día 7 empeora con fiebre de 38.8 °C, dolor maxilar y rinorrea purulenta.","p":"¿Qué conducta es adecuada?","o":["Sintomáticos y esperar 2 semanas más","Antibiótico: amoxicilina con ácido clavulánico 875/125 mg cada 12 horas","Radiografía de Waters antes de decidir","Referir a otorrinolaringología"],"r":1,"e":"El empeoramiento después de una mejoría inicial (doble empeoramiento) es criterio de sinusitis bacteriana; la elección es amoxicilina con ácido clavulánico por 5 a 7 días.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 6 años con sinusitis que ahora presenta edema y eritema del párpado, dolor al mover el ojo y visión doble.","p":"¿Cuál es la conducta?","o":["Antibiótico oral y cita en una semana","Referencia urgente por sospecha de complicación orbitaria","Compresas frías","Antihistamínico"],"r":1,"e":"Edema periorbitario, dolor con movimientos oculares o alteraciones visuales sugieren celulitis orbitaria, complicación grave que requiere referencia urgente.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Sobre la rinosinusitis aguda.","p":"¿Qué seno se afecta con más frecuencia en niños pequeños?","o":["Frontal","Etmoidal","Esfenoidal","Maxilar"],"r":1,"e":"En niños el seno etmoidal es el más afectado porque es el primero en desarrollarse; en adultos, el maxilar.","f":"Manual CTO, Otorrinolaringología, capítulo 3."},{"c":"Lactante de 10 meses con tos, fiebre y frecuencia respiratoria de 56 por minuto con tiraje intercostal.","p":"¿Qué interpretas?","o":["Resfriado común","Datos de neumonía; requiere valoración urgente","Faringitis viral","Otitis media"],"r":1,"e":"De 2 a 11 meses, 50 o más respiraciones por minuto es taquipnea; con tiraje sugiere neumonía grave y requiere manejo urgente.","f":"Organización Mundial de la Salud, Atención Integrada a las Enfermedades Prevalentes de la Infancia; Guía IMSS-062-08."},{"c":"Mujer embarazada de 28 semanas con fiebre de 39 °C, mialgias y tos de 24 horas, en temporada de influenza.","p":"¿Qué indicas?","o":["Solo paracetamol","Oseltamivir 75 mg cada 12 horas por 5 días","Amoxicilina por 7 días","Esperar el resultado de la prueba antes de cualquier tratamiento"],"r":1,"e":"La embarazada es de alto riesgo para complicaciones de influenza; se indica oseltamivir lo antes posible, de preferencia en las primeras 48 horas, sin esperar la prueba.","f":"Ficha de oseltamivir de GCHE2 (etiqueta oficial y Centros para el Control y la Prevención de Enfermedades)."},{"c":"Padre de un niño de 2 años con resfriado pregunta cuándo regresar.","p":"¿Qué le indicas?","o":["Solo si la fiebre dura más de 10 días","Si la fiebre dura más de 3 días, empeora tras 3 a 5 días o no mejora en 7 a 10 días, o si aparece algún dato de alarma","Nunca, se cura solo","Cada 24 horas para revisión"],"r":1,"e":"La guía mexicana de niños indica revaloración con fiebre de más de 3 días, empeoramiento o síntomas nuevos a los 3 a 5 días, falta de mejoría a los 7 a 10 días, o cualquier dato de alarma.","f":"Guía IMSS-062-08, actualización 2016."}],"audio":[["¿Cuál es la causa más frecuente del resfriado común?","El rinovirus, a cualquier edad."],["¿Se da antibiótico en el resfriado?","No. Tratamiento sintomático; y en menores de 6 años, sin antitusivos ni antigripales."],["¿Cuáles son los criterios de Centor?","Fiebre, ausencia de tos, adenopatía cervical anterior dolorosa y exudado amigdalino. McIsaac suma 1 de 3 a 14 años y resta 1 de 45 en adelante."],["¿Qué hago con Centor de 0 a 1?","Nada de prueba ni antibiótico: probablemente viral."],["¿Cuál es el tratamiento de la faringitis estreptocócica?","Penicilina benzatínica dosis única, o penicilina V o amoxicilina por 10 días."],["¿Qué dosis de penicilina benzatínica?","600 mil unidades si pesa menos de 27 kilos; un millón 200 mil si pesa más."],["¿Qué previene el tratamiento antibiótico de la faringitis?","La fiebre reumática, si se inicia en los primeros 9 días; no previene la glomerulonefritis."],["¿Qué sospecho con exantema tras amoxicilina en un adolescente con faringitis?","Mononucleosis infecciosa por virus de Epstein-Barr."],["¿Cuál es el hallazgo clave de la otitis media aguda?","La membrana timpánica abombada."],["¿Cuál es el tratamiento de la otitis media?","Amoxicilina a dosis alta, 80 a 90 miligramos por kilo al día en dos tomas; con clavulánico si tomó amoxicilina el último mes o hay conjuntivitis purulenta."],["¿Cuándo es bacteriana la sinusitis?","Con 10 días o más sin mejoría, inicio grave con fiebre de 39 o más, o empeoramiento tras una mejoría inicial."],["¿Qué frecuencia respiratoria es taquipnea?","60 o más en menores de 2 meses, 50 o más de 2 a 11 meses y 40 o más de 1 a 4 años."]],"profundizar":{"harrison":[[35,"Síntomas de vías respiratorias altas: otalgia, síntomas de senos paranasales y faringodinia"]],"guias":[["Diagnóstico y manejo de la infección aguda de vías aéreas superiores en pacientes mayores de 3 meses hasta 18 años de edad, IMSS-062-08, actualización 2016","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/062GER.pdf"],["Diagnóstico y tratamiento de faringoamigdalitis aguda, IMSS-073-08, 2008 (sin enlace oficial por ahora; ver diferencias)",""]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Enfermedades Infecciosas, capítulo 6, páginas 50 a 52 del archivo.","Manual CTO, Otorrinolaringología, capítulos 2 (otitis media aguda), 3 (rinosinusitis) y 5 (faringe).","Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 35 y cuadro 35-5.","Guía de Práctica Clínica IMSS-062-08, actualización 2016.","Guía de Práctica Clínica IMSS-073-08 (2008).","Fichas verificadas de paracetamol, azitromicina y oseltamivir en GCHE2 (etiquetas oficiales)."]}};
